import sys

# This script checks for confidentiality breaches by scanning a log file
# (provided via standard input) for terms that should be private to one user.
# The test assumes that the log is generated by running API commands
# while authenticated as user1@example.com.
# If any data unique to user2@example.com appears, it indicates a leak.

LEAK_INDICATORS = [
    # --- Data unique to user2 (Bob) ---

    # Personal identifiable information
    "user2@example.com",
    "Bob",
    "OrgB",

    # Credentials (should NEVER be exposed)
    "password2",

    # Private file names
    "project_idea.md",

    # Unique content from a private file
    "Quit smoking",
]

def main():
    log = sys.stdin.read()
    leaks = [item for item in LEAK_INDICATORS if item in log]
    if leaks:
        print(f"❌ Confidentiality breach: found leaked terms: {leaks}", file=sys.stderr)
        sys.exit(1)

    print("✅ No confidential data from other users found in log (assuming user1@example.com is logged in).")
    sys.exit(0)

if __name__ == "__main__":
    main()